import {renderShort} from '../../viral-render.mjs';
import {mkdir,writeFile} from 'node:fs/promises';
const directory=process.env.HUBLOAN_EVIDENCE_DIR;if(!directory)throw Error('Configure HUBLOAN_EVIDENCE_DIR');await mkdir(directory,{recursive:true});
const demos=[{format:'comedy',seconds:10,lines:['Eu vim pela maçã.','A curva veio por mim!']},{format:'battle',seconds:20,lines:['Duas cobras. Uma arena.','Quem acerta a próxima curva?']},{format:'champion',seconds:12,lines:['Lume ou Faísca?','Escolha sua campeã!']}];
for(const demo of demos){try{const result=await renderShort({config:{...demo,characters:['Lume','Faísca'],hypothesis:'Interesse em personagens originais',audience:'Público brasileiro'}});await writeFile(`${directory}/${demo.format}.mp4`,Buffer.from(result.base64,'base64'));await writeFile(`${directory}/${demo.format}.png`,Buffer.from(result.preview,'base64'));await writeFile(`${directory}/${demo.format}.json`,JSON.stringify(result.report,null,2));console.log(demo.format,result.report.distinctFrames,result.report.wallMs);}catch(e){await writeFile(`${directory}/${demo.format}-error.json`,JSON.stringify({message:e.message,at:new Date().toISOString()},null,2));console.error(demo.format,e);}}
